refentry.refsect1:
&reftitle.description;
arrayarray_column arrayarray intstringnullcolumn_key intstringnullindex_key&null;
A função array_column retorna os valores de uma coluna do array informado, indentificada pelo column_key. Opcionalmente, uma index_key pode ser informada para indexar os valores do array retornado pelos valores da coluna index_key do array.
array é tratado como uma lista de linhas, cada uma sendo um array ou objeto; uma coluna é a entrada ou propriedade nomeada por column_key em cada linha. Linhas que não sejam arrays nem objetos, e linhas sem essa entrada ou propriedade, são ignoradas sem emitir avisos. As chaves de array nunca são preservadas.

  &reftitle.examples;



    Obtém a coluna first_name dos registros


<?php

// Array representando um possível resultado retornado de um banco de dados
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$first_names = array_column($records, 'first_name');
print_r($first_names);

?>


    &example.outputs;


Array
(
    [0] => John
    [1] => Sally
    [2] => Jane
    [3] => Peter
)








     Obtém a coluna last_name dos registros, indexados pela coluna "id"



<?php

// Usando o array $records do Exemplo #1
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$last_names = array_column($records, 'last_name', 'id');
print_r($last_names);

?>


    &example.outputs;


Array
(
    [2135] => Doe
    [3245] => Smith
    [5342] => Jones
    [5623] => Doe
)








     Obtém a coluna de nomes de usuários da propriedade pública "username" de um
     objeto



<?php

class User
{
    public $username;

    public function __construct(string $username)
    {
        $this->username = $username;
    }
}

$users = [
    new User('user 1'),
    new User('user 2'),
    new User('user 3'),
];

print_r(array_column($users, 'username'));

?>


    &example.outputs;


Array
(
    [0] => user 1
    [1] => user 2
    [2] => user 3
)








     Obtém a coluna de nomes da propriedade privada "name" de um objeto
     utilizando os métodos mágicos __isset() e __get()



<?php

class Person
{
    private $name;

    public function __construct(string $name)
    {
        $this->name = $name;
    }

    public function __get($prop)
    {
        return $this->$prop;
    }

    public function __isset($prop) : bool
    {
        return isset($this->$prop);
    }
}

$people = [
    new Person('Fred'),
    new Person('Jane'),
    new Person('John'),
];

print_r(array_column($people, 'name'));
?>


    &example.outputs;


Array
(
    [0] => Fred
    [1] => Jane
    [2] => John
)



   Se __isset() não for fornecido, o objeto
   não contribuirá com nenhuma entrada para o array retornado.
